{
  "name": "USB设备连通性诊断组件",
  "name_en": "USB Device Connectivity Diagnostic Component",
  "manufacturer": "",
  "description": "这是一个非实体软件组件，用于在实验系统中描述USB设备并执行连接诊断。它主要检查设备是否可见、是否映射为POSIX端口、端口路径是否有效、端口能否打开，以及是否能够进行命令读写，以帮助排查仪器与主机之间的USB连接问题。",
  "description_en": "This is a non-physical software component used in laboratory systems to describe USB devices and perform connectivity diagnostics. It checks whether a device is visible, whether it appears as a POSIX port, whether port paths are valid, whether ports can be opened, and whether command read/write is possible, helping troubleshoot USB connections between instruments and host computers.",
  "tag_hints": [
    "USB connectivity diagnostics",
    "POSIX serial port detection",
    "device enumeration",
    "port open test",
    "USB command I/O check",
    "instrument connection troubleshooting"
  ],
  "actions": [
    {
      "action_name": "auto-isVisible",
      "description": "检查目标USB设备是否被系统识别并可见。",
      "description_en": "Check whether the target USB device is detected and visible to the system."
    },
    {
      "action_name": "auto-isVisibleOnUSBHub",
      "description": "检查目标设备是否在USB集线器枚举中可见。",
      "description_en": "Check whether the target device is visible in USB hub enumeration."
    },
    {
      "action_name": "auto-diagnoseConnectivity",
      "description": "执行USB设备与端口的连通性诊断。",
      "description_en": "Run connectivity diagnostics for the USB device and its ports."
    },
    {
      "action_name": "auto-isVisibleAsPOSIXPort",
      "description": "检查设备是否以POSIX端口形式出现在系统中。",
      "description_en": "Check whether the device appears in the system as a POSIX port."
    },
    {
      "action_name": "auto-isValidPOSIXPath",
      "description": "验证POSIX设备路径是否有效。",
      "description_en": "Validate whether the POSIX device path is valid."
    },
    {
      "action_name": "auto-hasUniquePOSIXPortMatch",
      "description": "检查是否能唯一匹配到一个POSIX端口。",
      "description_en": "Check whether there is a unique matching POSIX port."
    },
    {
      "action_name": "auto-bsdPath",
      "description": "获取或解析对应的BSD设备路径。",
      "description_en": "Get or resolve the corresponding BSD device path."
    },
    {
      "action_name": "auto-bsdPathMatches",
      "description": "检查BSD设备路径是否与预期匹配。",
      "description_en": "Check whether the BSD device path matches the expected value."
    },
    {
      "action_name": "auto-portCanBeOpened",
      "description": "检查已识别端口是否可以打开。",
      "description_en": "Check whether the identified port can be opened."
    },
    {
      "action_name": "auto-usbPortCanBeOpened",
      "description": "检查USB端口是否可以打开。",
      "description_en": "Check whether the USB port can be opened."
    },
    {
      "action_name": "auto-usbPort",
      "description": "获取USB端口标识或端口信息。",
      "description_en": "Get the USB port identifier or port information."
    },
    {
      "action_name": "auto-posixPort",
      "description": "获取对应的POSIX端口路径或标识。",
      "description_en": "Get the corresponding POSIX port path or identifier."
    },
    {
      "action_name": "auto-posixPortCanBeOpened",
      "description": "检查POSIX端口是否可以打开。",
      "description_en": "Check whether the POSIX port can be opened."
    },
    {
      "action_name": "auto-canReadWritePOSIXCommands",
      "description": "检查是否可通过POSIX端口进行命令读写。",
      "description_en": "Check whether commands can be read and written through the POSIX port."
    },
    {
      "action_name": "auto-canReadWriteUSBCommands",
      "description": "检查是否可通过USB接口进行命令读写。",
      "description_en": "Check whether commands can be read and written through the USB interface."
    },
    {
      "action_name": "auto-assertTrue",
      "description": "断言某项检查结果为真。",
      "description_en": "Assert that a diagnostic property or check result is true."
    },
    {
      "action_name": "auto-assertFalseOrRaise",
      "description": "断言某项检查结果为假，否则抛出异常。",
      "description_en": "Assert that a diagnostic property or check result is false; otherwise raise an exception."
    },
    {
      "action_name": "auto-assertRaise",
      "description": "断言某项检查应触发异常。",
      "description_en": "Assert that a diagnostic check is expected to raise an exception."
    },
    {
      "action_name": "auto-assertEqual",
      "description": "断言某项检查结果等于期望值。",
      "description_en": "Assert that a diagnostic result equals the expected value."
    },
    {
      "action_name": "auto-assertNotEqual",
      "description": "断言某项检查结果不等于期望值。",
      "description_en": "Assert that a diagnostic result does not equal the expected value."
    },
    {
      "action_name": "auto-report",
      "description": "生成USB设备连通性诊断报告。",
      "description_en": "Generate a USB device connectivity diagnostic report."
    }
  ]
}

